1	// Package rollup downsamples a time series into fixed windows aligned to
2	// the Unix epoch, and merges rollups that share a window size.
3	//
4	// A Roller is safe for concurrent use: samples may be filed, windows read,
5	// and rollers merged from multiple goroutines at once. Every read observes
6	// an internally consistent snapshot, and a merge or batch is visible to
7	// other callers either in full or not at all.
8	package rollup
9	
10	import (
11		"errors"
12		"math"
13		"math/big"
14		"math/bits"
15		"sort"
16		"sync"
17		"sync/atomic"
18		"time"
19	)
20	
21	// ErrOutOfOrder is returned by Add when a sample predates the most recent
22	// sample the roller has already accepted.
23	var ErrOutOfOrder = errors.New("rollup: out of order")
24	
25	// ErrWindowMismatch is returned by Merge when the two rollers use different
26	// window sizes.
27	var ErrWindowMismatch = errors.New("rollup: window mismatch")
28	
29	// ErrNonFinite is returned by Add and AddBatch when a sample value is NaN
30	// or an infinity. Such a sample is never filed: on Add the roller is left
31	// unchanged, and on AddBatch the whole batch is rejected as one unit.
32	var ErrNonFinite = errors.New("rollup: non-finite value")
33	
34	// Sample is one record in a batch passed to AddBatch: a value observed at
35	// one instant.
36	type Sample struct {
37		At    time.Time
38		Value float64
39	}
40	
41	// Window holds the aggregate statistics of the samples filed into one
42	// window. Start is the window's left-closed, right-open lower bound.
43	type Window struct {
44		Start time.Time
45		Count int64
46		Sum   float64
47		Min   float64
48		Max   float64
49	}
50	
51	// backWindow pairs a backfilled window with its exact bookkeeping.
52	type backWindow struct {
53		w  Window
54		st stats
55	}
56	
57	// Roller aggregates samples into fixed windows of a single size.
58	//
59	// The zero value is not usable; build one with New. All methods are safe
60	// to call concurrently from multiple goroutines.
61	type Roller struct {
62		// mu guards buckets, bstats, back, latest, and hasAny. window and id
63		// are fixed at construction and read without the lock.
64		//
65		// buckets and bstats are parallel flat slices kept sorted by window
66		// start: samples arrive in non-decreasing time order, so Add appends
67		// in amortized constant time, Windows reads out without re-sorting,
68		// and Merge is a single linear pass over both sides.
69		//
70		// back holds backfilled windows keyed by window start: a sample that
71		// lands before the newest window opens its bucket here, so a new
72		// window costs one map insert instead of shifting a sorted tail and a
73		// mass backfill stays linear. Once the number of backfilled windows
74		// catches up with buckets, they are sorted once and folded into it,
75		// amortizing that sort over the inserts. Every read consults both
76		// buckets and back, and no window start appears in both at the same
77		// time.
78		mu      sync.RWMutex
79		id      uint64
80		window  time.Duration
81		buckets []Window
82		bstats  []stats
83		back    map[time.Time]backWindow
84		latest  time.Time
85		hasAny  bool
86	}
87	
88	// idGen hands out unique roller IDs so Merge can lock two rollers in a
89	// consistent order and concurrent cross-merges cannot deadlock.
90	var idGen atomic.Uint64
91	
92	// New builds a roller with the given window size. It panics with
93	// "rollup: bad window" if window is not positive.
94	func New(window time.Duration) *Roller {
95		if window <= 0 {
96			panic("rollup: bad window")
97		}
98		return &Roller{
99			id:     idGen.Add(1),
100			window: window,
101		}
102	}
103	
104	// startOf returns the start of the window containing at, aligned to an
105	// integer multiple of the window size since the Unix epoch.
106	func (r *Roller) startOf(at time.Time) time.Time {
107		return alignStart(at, r.window.Nanoseconds())
108	}
109	
110	// alignStart returns the start of the window of width w nanoseconds
111	// containing at, aligned to an integer multiple of w since the Unix epoch.
112	// The arithmetic is exact for any time value, including ones whose
113	// nanosecond offset from the epoch does not fit in an int64.
114	func alignStart(at time.Time, w int64) time.Time {
115		sec := at.Unix()
116		nsec := int64(at.Nanosecond())
117		if sec >= -9223372036 && sec <= 9223372035 {
118			// sec*1e9+nsec fits in an int64. Rounding a negative ns down to
119			// a window multiple can reach ns-(w-1), so stay on the fast
120			// path only when that product cannot overflow either.
121			if ns := sec*1e9 + nsec; ns >= math.MinInt64+w-1 {
122				start := ns / w
123				if ns%w != 0 && ns < 0 {
124					start--
125				}
126				return time.Unix(0, start*w).UTC()
127			}
128		}
129		return windowStartWide(sec, nsec, w)
130	}
131	
132	// windowStartWide is the 128-bit slow path of alignStart, for times whose
133	// nanosecond offset from the epoch overflows an int64.
134	func windowStartWide(sec, nsec, w int64) time.Time {
135		// t = sec*1e9 + nsec as a 128-bit two's-complement value (hi, lo).
136		uhi, ulo := bits.Mul64(uint64(sec), uint64(1e9))
137		if sec < 0 {
138			uhi -= 1e9
139		}
140		hi := int64(uhi)
141		lo := ulo + uint64(nsec)
142		if lo < ulo {
143			hi++
144		}
145		// Round t down to a multiple of w: start = t - floorMod(t, w).
146		rem := floorMod128(hi, lo, w)
147		if lo < rem {
148			hi--
149		}
150		lo -= rem
151		// Split start into whole seconds and nanoseconds.
152		ns := floorMod128(hi, lo, 1e9)
153		if lo < ns {
154			hi--
155		}
156		lo -= ns
157		return time.Unix(quo128(hi, lo, 1e9), int64(ns)).UTC()
158	}
159	
160	// floorMod128 returns t mod y for the signed 128-bit value t = (hi<<64)|lo
161	// and positive y, with the result in [0, y).
162	func floorMod128(hi int64, lo uint64, y int64) uint64 {
163		yu := uint64(y)
164		if hi >= 0 {
165			return rem128(uint64(hi), lo, yu)
166		}
167		// Negate the 128-bit value, take the remainder, and reflect it back
168		// into [0, y) for floored (not truncated) division.
169		mlo := -lo
170		mhi := -uint64(hi)
171		if lo != 0 {
172			mhi--
173		}
174		if r := rem128(mhi, mlo, yu); r != 0 {
175			return yu - r
176		}
177		return 0
178	}
179	
180	// quo128 returns (hi<<64|lo)/y for a signed 128-bit dividend known to be an
181	// exact multiple of y, with a quotient that fits in an int64.
182	func quo128(hi int64, lo uint64, y int64) int64 {
183		yu := uint64(y)
184		if hi >= 0 {
185			q, _ := bits.Div64(uint64(hi), lo, yu)
186			return int64(q)
187		}
188		mlo := -lo
189		mhi := -uint64(hi)
190		if lo != 0 {
191			mhi--
192		}
193		q, _ := bits.Div64(mhi, mlo, yu)
194		return -int64(q)
195	}
196	
197	// rem128 returns (hi<<64 | lo) mod y for unsigned hi, lo and y > 0.
198	func rem128(hi, lo, y uint64) uint64 {
199		if hi >= y {
200			hi %= y
201		}
202		return bits.Rem64(hi, lo, y)
203	}
204	
205	// windowIndex locates the window starting at start in ws, which must be
206	// sorted by window start. The second result reports whether it exists;
207	// when it does not, the index is where it would be inserted to keep ws
208	// sorted, i.e. the first window whose start is not before start.
209	func windowIndex(ws []Window, start time.Time) (int, bool) {
210		sec, nsec := start.Unix(), int64(start.Nanosecond())
211		lo, hi := 0, len(ws)
212		for lo < hi {
213			m := int(uint(lo+hi) >> 1)
214			s := ws[m].Start
215			if ss, sn := s.Unix(), int64(s.Nanosecond()); ss < sec || (ss == sec && sn < nsec) {
216				lo = m + 1
217			} else {
218				hi = m
219			}
220		}
221		if lo < len(ws) {
222			if s := ws[lo].Start; s.Unix() == sec && int64(s.Nanosecond()) == nsec {
223				return lo, true
224			}
225		}
226		return lo, false
227	}
228	
229	// ensureStatsLocked grows bstats to match buckets and seeds bookkeeping
230	// for windows assembled without it. It costs nothing once the two slices
231	// are already in step, which they always are on the normal write paths.
232	func (r *Roller) ensureStatsLocked() {
233		if len(r.bstats) >= len(r.buckets) {
234			return
235		}
236		grown := make([]stats, len(r.buckets))
237		copy(grown, r.bstats)
238		for i := len(r.bstats); i < len(r.buckets); i++ {
239			grown[i].absorb(r.buckets[i])
240		}
241		r.bstats = grown
242	}
243	
244	// Add files a sample into its window. A non-finite value (NaN or an
245	// infinity) is rejected with ErrNonFinite. A sample earlier than the most
246	// recent accepted sample is rejected with ErrOutOfOrder. In either case
247	// the roller, including its most-recent marker, is left unchanged; a
248	// sample at the same instant as the marker is accepted and counted again.
249	//
250	// Concurrent Adds are serialized: each takes effect in the order it
251	// acquires the roller, and the out-of-order check is measured against the
252	// samples accepted before it in that order.
253	func (r *Roller) Add(at time.Time, value float64) error {
254		if math.IsNaN(value) || math.IsInf(value, 0) {
255			return ErrNonFinite
256		}
257		r.mu.Lock()
258		defer r.mu.Unlock()
259		if r.hasAny && at.Before(r.latest) {
260			return ErrOutOfOrder
261		}
262		r.ensureStatsLocked()
263		r.fileLocked(at, value)
264		r.latest = at
265		r.hasAny = true
266		return nil
267	}
268	
269	// AddBatch files a batch of samples as one atomic unit: either every
270	// sample takes effect or none does. The samples may arrive in any order
271	// and are not checked against each other; several samples at the same
272	// instant are each counted. Each sample is filed into its epoch-aligned
273	// window exactly as Add would file it.
274	//
275	// A batch holding any non-finite value is rejected with ErrNonFinite. If
276	// any sample predates the most recent sample the roller has already
277	// accepted, the whole batch is rejected with ErrOutOfOrder. Either kind of
278	// rejection leaves the roller and its most-recent marker unchanged.
279	// Otherwise the marker advances to the later of its previous value and the
280	// newest sample in the batch. A nil or empty batch is accepted, changes
281	// nothing, and does not advance the marker.
282	//
283	// The batch is atomic with respect to every other call on the roller:
284	// concurrent adds, batches, merges, range reads, and cursor creation
285	// observe the roller wholly before or wholly after the batch.
286	func (r *Roller) AddBatch(samples []Sample) error {
287		if len(samples) == 0 {
288			return nil
289		}
290		// Finiteness is a property of each value and is scanned across the
291		// whole batch first, so one NaN rejects the unit even when a stale
292		// sample sits earlier in the slice. Nothing is filed until the batch
293		// is fully validated.
294		for _, s := range samples {
295			if math.IsNaN(s.Value) || math.IsInf(s.Value, 0) {
296				return ErrNonFinite
297			}
298		}
299		r.mu.Lock()
300		defer r.mu.Unlock()
301		latest := samples[0].At
302		for _, s := range samples {
303			if r.hasAny && s.At.Before(r.latest) {
304				return ErrOutOfOrder
305			}
306			if s.At.After(latest) {
307				latest = s.At
308			}
309		}
310		r.ensureStatsLocked()
311		for _, s := range samples {
312			r.fileLocked(s.At, s.Value)
313		}
314		if r.hasAny && r.latest.After(latest) {
315			latest = r.latest
316		}
317		r.latest = latest
318		r.hasAny = true
319		return nil
320	}
321	
322	// fileLocked folds one sample into its window. The caller must hold mu
323	// and must already have cleared the non-finite and out-of-order checks.
324	func (r *Roller) fileLocked(at time.Time, value float64) {
325		start := r.startOf(at)
326		n := len(r.buckets)
327		switch {
328		case n == 0:
329			r.buckets = append(r.buckets, newBucket(start, value))
330			r.bstats = append(r.bstats, seedStats(value))
331		case !start.Before(r.buckets[n-1].Start):
332			// The common case: the sample lands in the newest window or
333			// just past it, so the sorted order is maintained for free.
334			if r.buckets[n-1].Start.Equal(start) {
335				addTo(&r.buckets[n-1], &r.bstats[n-1], value)
336			} else {
337				r.buckets = append(r.buckets, newBucket(start, value))
338				r.bstats = append(r.bstats, seedStats(value))
339			}
340		default:
341			// The sample belongs to an older window, which can only happen
342			// after a merge brought in windows past latest. A window that
343			// already exists is updated in place; a new one goes into the
344			// backfill map, so inserting it never shifts the sorted tail of
345			// buckets and the cost of a mass backfill stays linear in the
346			// number of windows accepted.
347			if i, ok := windowIndex(r.buckets, start); ok {
348				addTo(&r.buckets[i], &r.bstats[i], value)
349			} else if bw, ok := r.back[start]; ok {
350				addTo(&bw.w, &bw.st, value)
351				r.back[start] = bw
352			} else {
353				if r.back == nil {
354					r.back = make(map[time.Time]backWindow)
355				}
356				r.back[start] = backWindow{w: newBucket(start, value), st: seedStats(value)}
357				r.maybeFlushBack()
358			}
359		}
360	}
361	
362	// newBucket returns a window holding a single sample.
363	func newBucket(start time.Time, value float64) Window {
364		return Window{Start: start, Count: 1, Sum: value, Min: value, Max: value}
365	}
366	
367	// maybeFlushBack folds the backfilled windows into buckets once they
368	// number at least half as many as buckets, so the sorting and merge cost
369	// amortizes to constant time per backfilled window. The caller must hold
370	// mu.
371	func (r *Roller) maybeFlushBack() {
372		if len(r.back)*2 < len(r.buckets) {
373			return
374		}
375		bw, bs := r.sortedBackLocked()
376		r.buckets, r.bstats = mergeWindows(r.buckets, r.bstats, bw, bs)
377		r.back = nil
378	}
379	
380	// sortedBackLocked returns the backfilled windows in time order. The
381	// caller must hold mu; the returned slices are fresh and aligned and each
382	// stats owns an independent rational, so the result feeds merging writes.
383	func (r *Roller) sortedBackLocked() ([]Window, []stats) {
384		starts := make([]time.Time, 0, len(r.back))
385		for s := range r.back {
386			starts = append(starts, s)
387		}
388		sort.Slice(starts, func(i, j int) bool {
389			return starts[i].Before(starts[j])
390		})
391		ws := make([]Window, len(starts))
392		ss := make([]stats, len(starts))
393		for i, s := range starts {
394			bw := r.back[s]
395			ws[i] = bw.w
396			ss[i] = cloneStats(bw.st)
397		}
398		return ws, ss
399	}
400	
401	// sortedBackWindowsLocked returns just the backfilled windows in time
402	// order for display reads; their stored Sum/Min/Max already carry the
403	// canonical values, so no bookkeeping is touched.
404	func (r *Roller) sortedBackWindowsLocked() []Window {
405		starts := make([]time.Time, 0, len(r.back))
406		for s := range r.back {
407			starts = append(starts, s)
408		}
409		sort.Slice(starts, func(i, j int) bool {
410			return starts[i].Before(starts[j])
411		})
412		ws := make([]Window, len(starts))
413		for i, s := range starts {
414			ws[i] = r.back[s].w
415		}
416		return ws
417	}
418	
419	// cloneStats returns an independent copy of st, including its accumulator.
420	func cloneStats(st stats) stats {
421		if st.sum != nil {
422			st.sum = new(big.Int).Set(st.sum)
423		}
424		return st
425	}
426	
427	// mergeWindows returns the sorted union of two window sets, each sorted by
428	// window start, combining the statistics of windows that share a start
429	// under the fixed sum and extrema semantics. Windows only one side has are
430	// carried over. The results are always fresh: every returned stats owns an
431	// independent rational, so a later write to either input never reaches the
432	// output. It is a write-path helper for genuinely combining two sets.
433	func mergeWindows(aw []Window, as []stats, bw []Window, bs []stats) ([]Window, []stats) {
434		merged := make([]Window, 0, len(aw)+len(bw))
435		mstats := make([]stats, 0, len(aw)+len(bw))
436		i, j := 0, 0
437		for i < len(aw) && j < len(bw) {
438			switch {
439			case aw[i].Start.Before(bw[j].Start):
440				merged = append(merged, aw[i])
441				mstats = append(mstats, cloneStats(as[i]))
442				i++
443			case bw[j].Start.Before(aw[i].Start):
444				merged = append(merged, bw[j])
445				mstats = append(mstats, cloneStats(bs[j]))
446				j++
447			default:
448				w := aw[i]
449				st := cloneStats(as[i])
450				combineWindow(&w, &st, &bw[j], &bs[j])
451				merged = append(merged, w)
452				mstats = append(mstats, st)
453				i++
454				j++
455			}
456		}
457		for ; i < len(aw); i++ {
458			merged = append(merged, aw[i])
459			mstats = append(mstats, cloneStats(as[i]))
460		}
461		for ; j < len(bw); j++ {
462			merged = append(merged, bw[j])
463			mstats = append(mstats, cloneStats(bs[j]))
464		}
465		return merged, mstats
466	}
467	
468	// Window returns the bucket whose start matches start exactly. The second
469	// result is false when no bucket starts at that instant; no nearby bucket
470	// is substituted. The returned Window is a copy and stays valid no matter
471	// what is filed afterwards.
472	func (r *Roller) Window(start time.Time) (Window, bool) {
473		r.mu.RLock()
474		defer r.mu.RUnlock()
475		if i, ok := windowIndex(r.buckets, start); ok {
476			return r.buckets[i], true
477		}
478		if bw, ok := r.back[start.UTC()]; ok {
479			return bw.w, true
480		}
481		return Window{}, false
482	}
483	
484	// snapshotStatsLocked returns a time-ordered copy of every window and an
485	// independent stats per window, for merging and view derivation. Windows
486	// assembled without bookkeeping (the package's tests build some directly)
487	// are seeded into a local copy, so this stays a pure read even while
488	// holding only an RLock. The caller must hold mu.
489	func (r *Roller) snapshotStatsLocked() ([]Window, []stats) {
490		seeded := r.bstats
491		if len(seeded) < len(r.buckets) {
492			grown := make([]stats, len(r.buckets))
493			copy(grown, r.bstats)
494			for i := len(r.bstats); i < len(r.buckets); i++ {
495				grown[i].absorb(r.buckets[i])
496			}
497			seeded = grown
498		}
499		if len(r.back) == 0 {
500			ws := make([]Window, len(r.buckets))
501			copy(ws, r.buckets)
502			ss := make([]stats, len(seeded))
503			for i := range seeded {
504				ss[i] = cloneStats(seeded[i])
505			}
506			return ws, ss
507		}
508		bw, bs := r.sortedBackLocked()
509		return mergeWindows(r.buckets, seeded, bw, bs)
510	}
511	
512	// Windows returns all buckets in time order. An empty roller yields an
513	// empty slice. The result is a snapshot of one moment: samples filed after
514	// the call do not alter it.
515	func (r *Roller) Windows() []Window {
516		r.mu.RLock()
517		defer r.mu.RUnlock()
518		if len(r.back) == 0 {
519			out := make([]Window, len(r.buckets))
520			copy(out, r.buckets)
521			return out
522		}
523		return r.sortedUnionWindowsLocked()
524	}
525	
526	// sortedUnionWindowsLocked interleaves buckets and the backfill map in
527	// time order. The two sets hold disjoint starts, so windows are only
528	// copied, never recombined. The caller must hold mu.
529	func (r *Roller) sortedUnionWindowsLocked() []Window {
530		back := r.sortedBackWindowsLocked()
531		merged := make([]Window, 0, len(r.buckets)+len(back))
532		i, j := 0, 0
533		for i < len(r.buckets) && j < len(back) {
534			if r.buckets[i].Start.Before(back[j].Start) {
535				merged = append(merged, r.buckets[i])
536				i++
537			} else {
538				merged = append(merged, back[j])
539				j++
540			}
541		}
542		merged = append(merged, r.buckets[i:]...)
543		merged = append(merged, back[j:]...)
544		return merged
545	}
546	
547	// Range returns the buckets that overlap the half-open interval
548	// [from, to), in time order. The endpoints are attributed to windows by
549	// the same epoch-aligned, left-closed rule Add uses: the first bucket
550	// returned is the one containing from, and a bucket starting exactly at
551	// to is excluded. An interval whose end does not come after its start
552	// yields an empty slice, as does an interval no bucket overlaps. The
553	// result is a snapshot of one moment: samples filed after the call do not
554	// alter it.
555	func (r *Roller) Range(from, to time.Time) []Window {
556		r.mu.RLock()
557		defer r.mu.RUnlock()
558		out := []Window{}
559		if !from.Before(to) {
560			return out
561		}
562		var back []Window
563		if len(r.back) != 0 {
564			back = r.sortedBackWindowsLocked()
565		}
566		lo := r.startOf(from)
567		i, _ := windowIndex(r.buckets, lo)
568		j, _ := windowIndex(back, lo)
569		for {
570			var w Window
571			switch {
572			case i < len(r.buckets) && (j >= len(back) || r.buckets[i].Start.Before(back[j].Start)):
573				w = r.buckets[i]
574				i++
575			case j < len(back):
576				w = back[j]
577				j++
578			default:
579				return out
580			}
581			if !w.Start.Before(to) {
582				return out
583			}
584			out = append(out, w)
585		}
586	}
587	
588	// Cursor reads a fixed range of windows in batches. The windows are
589	// snapshot when the cursor is created: samples filed, backfilled, or
590	// merged in afterwards do not alter what the cursor returns, so batched
591	// iteration over a large range never tears, skips, or repeats a window,
592	// and the end of the range is reached deterministically no matter what is
593	// written while the cursor advances.
594	//
595	// A Cursor is safe to advance from multiple goroutines at once; each
596	// batch is handed out exactly once.
597	type Cursor struct {
598		// mu guards pos. windows is fixed at creation and read without the
599		// lock.
600		mu      sync.Mutex
601		windows []Window
602		pos     int
603	}
604	
605	// Cursor returns a cursor over the buckets overlapping the half-open
606	// interval [from, to), selected by the same rule as Range.
607	func (r *Roller) Cursor(from, to time.Time) *Cursor {
608		return &Cursor{windows: r.Range(from, to)}
609	}
610	
611	// Next returns the next batch of up to n windows, in time order. Batches
612	// are consecutive and non-overlapping: together they cover exactly the
613	// windows in the cursor's range. Once the range is exhausted, Next
614	// returns an empty slice and the cursor does not move. A non-positive n
615	// yields an empty slice and does not advance the cursor.
616	func (c *Cursor) Next(n int) []Window {
617		c.mu.Lock()
618		defer c.mu.Unlock()
619		rest := len(c.windows) - c.pos
620		if n <= 0 || rest == 0 {
621			return []Window{}
622		}
623		if n > rest {
624			n = rest
625		}
626		out := make([]Window, n)
627		copy(out, c.windows[c.pos:c.pos+n])
628		c.pos += n
629		return out
630	}
631	
632	// Merge folds other's buckets into this roller: counts and sums combine,
633	// minimums take the smaller, maximums take the larger, and buckets only one
634	// side has are carried over as-is. Merging does not affect out-of-order
635	// tracking. It panics with "rollup: nil roller" if other is nil, and
636	// returns ErrWindowMismatch, leaving this roller unchanged, if the window
637	// sizes differ.
638	//
639	// The merge is atomic with respect to every other call on either roller:
640	// concurrent readers see this roller wholly before or wholly after the
641	// merge, and a sample filed into other while the merge runs is either
642	// folded in completely or not at all. If the two rollers merge each other
643	// at the same time, the outcome matches some serial order of the two
644	// merges; neither is lost.
645	func (r *Roller) Merge(other *Roller) error {
646		if other == nil {
647			panic("rollup: nil roller")
648		}
649		if other.window != r.window {
650			return ErrWindowMismatch
651		}
652		if r == other {
653			r.mu.Lock()
654			defer r.mu.Unlock()
655			r.ensureStatsLocked()
656			if len(r.back) != 0 {
657				bw, bs := r.sortedBackLocked()
658				r.buckets, r.bstats = mergeWindows(r.buckets, r.bstats, bw, bs)
659				r.back = nil
660			}
661			for i := range r.buckets {
662				w := &r.buckets[i]
663				st := &r.bstats[i]
664				w.Count = satAdd(w.Count, w.Count)
665				st.double()
666				w.Sum = st.canonicalSum()
667				w.Min = canonicalMin(w.Min, st.negZero)
668				w.Max = canonicalMax(w.Max, st.negZero, st.posZero)
669			}
670			return nil
671		}
672		// Lock both rollers in ID order so simultaneous merges in
673		// opposite directions cannot deadlock.
674		first, second := r, other
675		if other.id < r.id {
676			first, second = other, r
677		}
678		first.mu.Lock()
679		second.mu.Lock()
680		defer second.mu.Unlock()
681		defer first.mu.Unlock()
682	
683		r.ensureStatsLocked()
684		other.ensureStatsLocked()
685	
686		switch {
687		case len(other.buckets) == 0 && len(other.back) == 0:
688			return nil
689		case len(r.buckets) == 0 && len(r.back) == 0:
690			r.buckets, r.bstats = other.snapshotStatsLocked()
691			return nil
692		}
693		var left, right []Window
694		var lst, rst []stats
695		left, lst = r.buckets, r.bstats
696		if len(r.back) != 0 {
697			bw, bs := r.sortedBackLocked()
698			left, lst = mergeWindows(r.buckets, r.bstats, bw, bs)
699		}
700		right, rst = other.buckets, other.bstats
701		if len(other.back) != 0 {
702			bw, bs := other.sortedBackLocked()
703			right, rst = mergeWindows(other.buckets, other.bstats, bw, bs)
704		}
705		// Both sides are sorted by window start, so the merge is one linear
706		// pass and one backing array, no per-bucket copies or lookups.
707		r.buckets, r.bstats = mergeWindows(left, lst, right, rst)
708		r.back = nil
709		return nil
710	}
711	
712	// satAdd returns a + b saturated at math.MaxInt64 instead of overflowing.
713	func satAdd(a, b int64) int64 {
714		if b > math.MaxInt64-a {
715			return math.MaxInt64
716		}
717		return a + b
718	}
