1	// Command rollupctl reads timestamped samples from a file, files them into
2	// fixed windows aligned to the Unix epoch, and prints, one per line, each
3	// window's start, count, sum, minimum, and maximum.
4	//
5	// Usage:
6	//
7	//	rollupctl --file <path> --window <duration> windows
8	//	rollupctl --file <path> --window <duration> --from <ns> --to <ns> range
9	//	rollupctl --file <path> --file <path> --window <duration> merge
10	//
11	// The input file holds one sample per line: an integer number of
12	// nanoseconds since the epoch, whitespace, then a floating-point value.
13	// Blank and whitespace-only lines carry no sample. Samples must arrive in
14	// non-decreasing time order.
15	//
16	// The windows subcommand prints every window. The range subcommand prints
17	// only the windows overlapping the half-open interval [--from, --to), both
18	// endpoints given as nanoseconds since the epoch. The merge subcommand
19	// aggregates two files with the same window duration and prints their
20	// windows combined into one listing.
21	//
22	// Exit codes: 0 success, 2 bad command-line arguments, 3 an input file
23	// does not exist or is a directory, 4 an input file's contents are
24	// invalid or the two files cannot be merged.
25	package main
26	
27	import (
28		"bufio"
29		"errors"
30		"fmt"
31		"io"
32		"math"
33		"math/big"
34		"os"
35		"strconv"
36		"strings"
37		"time"
38	
39		"github.com/Hulalalalalalalalalalala/metric-rollup/rollup"
40	)
41	
42	// maxLineBytes is the longest accepted physical input line, excluding the
43	// line terminator.
44	const maxLineBytes = 1024
45	
46	// rangeBatchSize is the number of windows the range subcommand asks the
47	// cursor for at a time, so printing a long interval streams in batches
48	// instead of materializing one listing per window.
49	const rangeBatchSize = 1024
50	
51	func main() {
52		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
53	}
54	
55	// command holds the parsed command line: which subcommand to run and the
56	// flag values it consumes.
57	type command struct {
58		sub            string
59		files          []string
60		window         string
61		from, to       string
62		hasFrom, hasTo bool
63	}
64	
65	// run parses args, reads the input file or files, and writes the window
66	// listing. It returns the process exit code; every diagnostic is a single
67	// line on stderr prefixed with "rollupctl: ".
68	func run(args []string, stdout, stderr io.Writer) int {
69		cmd, ok := parseArgs(args, stderr)
70		if !ok {
71			return 2
72		}
73		d, err := time.ParseDuration(cmd.window)
74		if err != nil {
75			argError(stderr, "invalid --window %q: %v", cmd.window, err)
76			return 2
77		}
78		if d <= 0 {
79			argError(stderr, "--window must be positive, got %s", d)
80			return 2
81		}
82	
83		switch cmd.sub {
84		case "range":
85			from, err := strconv.ParseInt(cmd.from, 10, 64)
86			if err != nil {
87				argError(stderr, "invalid --from %q: %v", cmd.from, err)
88				return 2
89			}
90			to, err := strconv.ParseInt(cmd.to, 10, 64)
91			if err != nil {
92				argError(stderr, "invalid --to %q: %v", cmd.to, err)
93				return 2
94			}
95			return runRange(cmd.files[len(cmd.files)-1], d, from, to, stdout, stderr)
96		case "merge":
97			return runMerge(cmd.files[0], cmd.files[1], d, stdout, stderr)
98		default:
99			return runWindows(cmd.files[len(cmd.files)-1], d, stdout, stderr)
100		}
101	}
102	
103	// runWindows prints every window of one file's samples.
104	func runWindows(path string, d time.Duration, stdout, stderr io.Writer) int {
105		roller, code := ingestFile(path, d, stderr)
106		if code != 0 {
107			return code
108		}
109		out := bufio.NewWriter(stdout)
110		writeWindows(out, roller.Windows())
111		return flush(out, stderr)
112	}
113	
114	// runRange prints the windows of one file's samples that overlap the
115	// half-open interval [from, to), advancing through them in cursor batches.
116	// An empty or backwards interval is not an error and prints nothing.
117	func runRange(path string, d time.Duration, from, to int64, stdout, stderr io.Writer) int {
118		roller, code := ingestFile(path, d, stderr)
119		if code != 0 {
120			return code
121		}
122		out := bufio.NewWriter(stdout)
123		cursor := roller.Cursor(time.Unix(0, from).UTC(), time.Unix(0, to).UTC())
124		for {
125			batch := cursor.Next(rangeBatchSize)
126			if len(batch) == 0 {
127				break
128			}
129			writeWindows(out, batch)
130		}
131		return flush(out, stderr)
132	}
133	
134	// runMerge aggregates two files with the same window duration and prints
135	// their combined windows. Both files are fully ingested before anything is
136	// printed, so a problem in either one leaves the listing empty.
137	func runMerge(pathA, pathB string, d time.Duration, stdout, stderr io.Writer) int {
138		rollerA, code := ingestFile(pathA, d, stderr)
139		if code != 0 {
140			return code
141		}
142		rollerB, code := ingestFile(pathB, d, stderr)
143		if code != 0 {
144			return code
145		}
146		if err := rollerA.Merge(rollerB); err != nil {
147			writeMergeError(stderr, pathA, pathB, err)
148			return 4
149		}
150		out := bufio.NewWriter(stdout)
151		writeWindows(out, rollerA.Windows())
152		return flush(out, stderr)
153	}
154	
155	// writeWindows prints one line per window: start, count, sum, min, max.
156	func writeWindows(out *bufio.Writer, ws []rollup.Window) {
157		for _, w := range ws {
158			fmt.Fprintf(out, "%s %d %s %s %s\n",
159				unixNanoText(w.Start), w.Count,
160				formatFloat(w.Sum), formatFloat(w.Min), formatFloat(w.Max))
161		}
162	}
163	
164	// flush flushes out and reports a write failure as exit code 1.
165	func flush(out *bufio.Writer, stderr io.Writer) int {
166		if err := out.Flush(); err != nil {
167			fmt.Fprintf(stderr, "rollupctl: %s\n", err)
168			return 1
169		}
170		return 0
171	}
172	
173	// argError writes one command-line usage diagnostic.
174	func argError(stderr io.Writer, format string, a ...any) {
175		fmt.Fprintf(stderr, "rollupctl: "+format+"\n", a...)
176	}
177	
178	// writeMergeError writes the one merge diagnostic: the two file names in
179	// command-line order, separated by a comma and a space, followed by the
180	// reason the merge could not combine them.
181	func writeMergeError(stderr io.Writer, pathA, pathB string, err error) {
182		fmt.Fprintf(stderr, "rollupctl: %s, %s: %v\n", pathA, pathB, err)
183	}
184	
185	// parseArgs extracts the subcommand and the flag values. Flags may stand
186	// on either side of the subcommand, Go-style: --name value, --name=value,
187	// with one or two leading dashes.
188	func parseArgs(args []string, stderr io.Writer) (command, bool) {
189		fail := func(format string, a ...any) (command, bool) {
190			argError(stderr, format, a...)
191			return command{}, false
192		}
193		var cmd command
194		sub := ""
195		flagsEnded := false
196		for i := 0; i < len(args); i++ {
197			a := args[i]
198			if !flagsEnded && a == "--" {
199				flagsEnded = true
200				continue
201			}
202			if flagsEnded || !strings.HasPrefix(a, "-") || a == "-" {
203				if sub != "" || (a != "windows" && a != "range" && a != "merge") {
204					return fail("unexpected argument %q", a)
205				}
206				sub = a
207				continue
208			}
209			name := a[1:]
210			if strings.HasPrefix(name, "-") {
211				name = name[1:]
212			}
213			value := ""
214			inline := false
215			if k := strings.IndexByte(name, '='); k >= 0 {
216				value = name[k+1:]
217				name = name[:k]
218				inline = true
219			}
220			switch name {
221			case "file", "window", "from", "to":
222				if !inline {
223					i++
224					if i >= len(args) {
225						return fail("flag --%s needs a value", name)
226					}
227					value = args[i]
228				}
229				if value == "" {
230					return fail("flag --%s needs a value", name)
231				}
232				switch name {
233				case "file":
234					cmd.files = append(cmd.files, value)
235				case "window":
236					cmd.window = value
237				case "from":
238					cmd.from, cmd.hasFrom = value, true
239				case "to":
240					cmd.to, cmd.hasTo = value, true
241				}
242			default:
243				return fail("unexpected argument %q", a)
244			}
245		}
246		cmd.sub = sub
247		if sub == "" {
248			return fail("expected a subcommand: windows, range, or merge")
249		}
250		if len(cmd.files) == 0 {
251			return fail("--file is required")
252		}
253		switch sub {
254		case "merge":
255			if cmd.hasFrom || cmd.hasTo {
256				return fail("--from and --to belong to the range subcommand")
257			}
258			if len(cmd.files) != 2 {
259				return fail("merge takes exactly two --file arguments, got %d", len(cmd.files))
260			}
261		case "range":
262			if len(cmd.files) != 1 {
263				return fail("range takes exactly one --file argument, got %d", len(cmd.files))
264			}
265			if !cmd.hasFrom {
266				return fail("--from is required")
267			}
268			if !cmd.hasTo {
269				return fail("--to is required")
270			}
271		default: // windows
272			if cmd.hasFrom || cmd.hasTo {
273				return fail("--from and --to belong to the range subcommand")
274			}
275		}
276		if cmd.window == "" {
277			return fail("--window is required")
278		}
279		return cmd, true
280	}
281	
282	// ingestFile opens one input file and streams its samples into a fresh
283	// roller. It returns a non-zero exit code after writing one diagnostic if
284	// the file cannot be opened or its contents are invalid.
285	func ingestFile(path string, d time.Duration, stderr io.Writer) (*rollup.Roller, int) {
286		info, err := os.Stat(path)
287		if err != nil {
288			fmt.Fprintf(stderr, "rollupctl: %s\n", err)
289			return nil, 3
290		}
291		if info.IsDir() {
292			fmt.Fprintf(stderr, "rollupctl: %s: is a directory\n", path)
293			return nil, 3
294		}
295		f, err := os.Open(path)
296		if err != nil {
297			fmt.Fprintf(stderr, "rollupctl: %s\n", err)
298			return nil, 3
299		}
300		roller, code := ingest(f, path, d, stderr)
301		f.Close()
302		if code != 0 {
303			return nil, code
304		}
305		return roller, 0
306	}
307	
308	// ingest streams the samples from in into a fresh roller. On any content
309	// problem it returns code 4 after writing one diagnostic naming the file
310	// and line; no sample lines are printed by the caller in that case.
311	func ingest(in io.Reader, name string, d time.Duration, stderr io.Writer) (*rollup.Roller, int) {
312		contentError := func(line int, reason string) (*rollup.Roller, int) {
313			fmt.Fprintf(stderr, "rollupctl: %s:%d: %s\n", name, line, reason)
314			return nil, 4
315		}
316	
317		// The line buffer is capped at one byte over the limit, so a longer
318		// line fails immediately instead of growing with the file.
319		sc := bufio.NewScanner(in)
320		sc.Buffer(make([]byte, maxLineBytes+1), maxLineBytes+1)
321	
322		roller := rollup.New(d)
323		line := 0
324		samples := 0
325		for sc.Scan() {
326			line++
327			text := sc.Text()
328			if strings.TrimSpace(text) == "" {
329				continue
330			}
331			fields := strings.Fields(text)
332			if len(fields) != 2 {
333				return contentError(line, "expected a nanosecond timestamp and a value separated by whitespace")
334			}
335			ns, err := strconv.ParseInt(fields[0], 10, 64)
336			if err != nil {
337				return contentError(line, fmt.Sprintf("invalid timestamp %q", fields[0]))
338			}
339			value, err := strconv.ParseFloat(fields[1], 64)
340			if err != nil {
341				return contentError(line, fmt.Sprintf("invalid value %q", fields[1]))
342			}
343			if math.IsNaN(value) || math.IsInf(value, 0) {
344				return contentError(line, "value must be finite")
345			}
346			if err := roller.Add(time.Unix(0, ns).UTC(), value); err != nil {
347				return contentError(line, err.Error())
348			}
349			samples++
350		}
351		if err := sc.Err(); err != nil {
352			if errors.Is(err, bufio.ErrTooLong) {
353				// The over-long line is the one after every line already
354				// delivered, including an unterminated last line.
355				return contentError(line+1, "line is longer than 1024 bytes")
356			}
357			fmt.Fprintf(stderr, "rollupctl: %s: %v\n", name, err)
358			return nil, 3
359		}
360		if samples == 0 {
361			return contentError(0, "no samples found")
362		}
363		return roller, 0
364	}
365	
366	// formatFloat writes a float64 in its shortest round-trippable form; a
367	// negative zero keeps its sign and renders as -0.
368	func formatFloat(v float64) string {
369		return strconv.FormatFloat(v, 'g', -1, 64)
370	}
371	
372	var bigBillion = big.NewInt(1e9)
373	
374	// unixNanoText writes a window start as a signed integer count of
375	// nanoseconds since the epoch even when it falls outside the int64 range,
376	// so a start aligned past it is printed exactly instead of clamped.
377	func unixNanoText(t time.Time) string {
378		n := new(big.Int).Mul(big.NewInt(t.Unix()), bigBillion)
379		n.Add(n, big.NewInt(int64(t.Nanosecond())))
380		return n.String()
381	}
