// Command rollupctl reads timestamped samples from a file, files them into
// fixed windows aligned to the Unix epoch, and prints, one per line, each
// window's start, count, sum, minimum, and maximum.
//
// Usage:
//
//	rollupctl --file <path> --window <duration> windows
//	rollupctl --file <path> --window <duration> --from <ns> --to <ns> range
//	rollupctl --file <path> --file <path> --window <duration> merge
//
// The input file holds one sample per line: an integer number of
// nanoseconds since the epoch, whitespace, then a floating-point value.
// Blank and whitespace-only lines carry no sample. Samples must arrive in
// non-decreasing time order.
//
// The windows subcommand prints every window. The range subcommand prints
// only the windows overlapping the half-open interval [--from, --to), both
// endpoints given as nanoseconds since the epoch. The merge subcommand
// aggregates two files with the same window duration and prints their
// windows combined into one listing.
//
// Exit codes: 0 success, 2 bad command-line arguments, 3 an input file
// does not exist or is a directory, 4 an input file's contents are
// invalid or the two files cannot be merged.
package main

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"math"
	"math/big"
	"os"
	"strconv"
	"strings"
	"time"

	"github.com/Hulalalalalalalalalalala/metric-rollup/rollup"
)

// maxLineBytes is the longest accepted physical input line, excluding the
// line terminator.
const maxLineBytes = 1024

// rangeBatchSize is the number of windows the range subcommand asks the
// cursor for at a time, so printing a long interval streams in batches
// instead of materializing one listing per window.
const rangeBatchSize = 1024

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

// command holds the parsed command line: which subcommand to run and the
// flag values it consumes.
type command struct {
	sub            string
	files          []string
	window         string
	from, to       string
	hasFrom, hasTo bool
}

// run parses args, reads the input file or files, and writes the window
// listing. It returns the process exit code; every diagnostic is a single
// line on stderr prefixed with "rollupctl: ".
func run(args []string, stdout, stderr io.Writer) int {
	cmd, ok := parseArgs(args, stderr)
	if !ok {
		return 2
	}
	d, err := time.ParseDuration(cmd.window)
	if err != nil {
		argError(stderr, "invalid --window %q: %v", cmd.window, err)
		return 2
	}
	if d <= 0 {
		argError(stderr, "--window must be positive, got %s", d)
		return 2
	}

	switch cmd.sub {
	case "range":
		from, err := strconv.ParseInt(cmd.from, 10, 64)
		if err != nil {
			argError(stderr, "invalid --from %q: %v", cmd.from, err)
			return 2
		}
		to, err := strconv.ParseInt(cmd.to, 10, 64)
		if err != nil {
			argError(stderr, "invalid --to %q: %v", cmd.to, err)
			return 2
		}
		return runRange(cmd.files[len(cmd.files)-1], d, from, to, stdout, stderr)
	case "merge":
		return runMerge(cmd.files[0], cmd.files[1], d, stdout, stderr)
	default:
		return runWindows(cmd.files[len(cmd.files)-1], d, stdout, stderr)
	}
}

// runWindows prints every window of one file's samples.
func runWindows(path string, d time.Duration, stdout, stderr io.Writer) int {
	roller, code := ingestFile(path, d, stderr)
	if code != 0 {
		return code
	}
	out := bufio.NewWriter(stdout)
	writeWindows(out, roller.Windows())
	return flush(out, stderr)
}

// runRange prints the windows of one file's samples that overlap the
// half-open interval [from, to), advancing through them in cursor batches.
// An empty or backwards interval is not an error and prints nothing.
func runRange(path string, d time.Duration, from, to int64, stdout, stderr io.Writer) int {
	roller, code := ingestFile(path, d, stderr)
	if code != 0 {
		return code
	}
	out := bufio.NewWriter(stdout)
	cursor := roller.Cursor(time.Unix(0, from).UTC(), time.Unix(0, to).UTC())
	for {
		batch := cursor.Next(rangeBatchSize)
		if len(batch) == 0 {
			break
		}
		writeWindows(out, batch)
	}
	return flush(out, stderr)
}

// runMerge aggregates two files with the same window duration and prints
// their combined windows. Both files are fully ingested before anything is
// printed, so a problem in either one leaves the listing empty.
func runMerge(pathA, pathB string, d time.Duration, stdout, stderr io.Writer) int {
	rollerA, code := ingestFile(pathA, d, stderr)
	if code != 0 {
		return code
	}
	rollerB, code := ingestFile(pathB, d, stderr)
	if code != 0 {
		return code
	}
	if err := rollerA.Merge(rollerB); err != nil {
		writeMergeError(stderr, pathA, pathB, err)
		return 4
	}
	out := bufio.NewWriter(stdout)
	writeWindows(out, rollerA.Windows())
	return flush(out, stderr)
}

// writeWindows prints one line per window: start, count, sum, min, max.
func writeWindows(out *bufio.Writer, ws []rollup.Window) {
	for _, w := range ws {
		fmt.Fprintf(out, "%s %d %s %s %s\n",
			unixNanoText(w.Start), w.Count,
			formatFloat(w.Sum), formatFloat(w.Min), formatFloat(w.Max))
	}
}

// flush flushes out and reports a write failure as exit code 1.
func flush(out *bufio.Writer, stderr io.Writer) int {
	if err := out.Flush(); err != nil {
		fmt.Fprintf(stderr, "rollupctl: %s\n", err)
		return 1
	}
	return 0
}

// argError writes one command-line usage diagnostic.
func argError(stderr io.Writer, format string, a ...any) {
	fmt.Fprintf(stderr, "rollupctl: "+format+"\n", a...)
}

// writeMergeError writes the one merge diagnostic: the two file names in
// command-line order, separated by a comma and a space, followed by the
// reason the merge could not combine them.
func writeMergeError(stderr io.Writer, pathA, pathB string, err error) {
	fmt.Fprintf(stderr, "rollupctl: %s, %s: %v\n", pathA, pathB, err)
}

// parseArgs extracts the subcommand and the flag values. Flags may stand
// on either side of the subcommand, Go-style: --name value, --name=value,
// with one or two leading dashes.
func parseArgs(args []string, stderr io.Writer) (command, bool) {
	fail := func(format string, a ...any) (command, bool) {
		argError(stderr, format, a...)
		return command{}, false
	}
	var cmd command
	sub := ""
	flagsEnded := false
	for i := 0; i < len(args); i++ {
		a := args[i]
		if !flagsEnded && a == "--" {
			flagsEnded = true
			continue
		}
		if flagsEnded || !strings.HasPrefix(a, "-") || a == "-" {
			if sub != "" || (a != "windows" && a != "range" && a != "merge") {
				return fail("unexpected argument %q", a)
			}
			sub = a
			continue
		}
		name := a[1:]
		if strings.HasPrefix(name, "-") {
			name = name[1:]
		}
		value := ""
		inline := false
		if k := strings.IndexByte(name, '='); k >= 0 {
			value = name[k+1:]
			name = name[:k]
			inline = true
		}
		switch name {
		case "file", "window", "from", "to":
			if !inline {
				i++
				if i >= len(args) {
					return fail("flag --%s needs a value", name)
				}
				value = args[i]
			}
			if value == "" {
				return fail("flag --%s needs a value", name)
			}
			switch name {
			case "file":
				cmd.files = append(cmd.files, value)
			case "window":
				cmd.window = value
			case "from":
				cmd.from, cmd.hasFrom = value, true
			case "to":
				cmd.to, cmd.hasTo = value, true
			}
		default:
			return fail("unexpected argument %q", a)
		}
	}
	cmd.sub = sub
	if sub == "" {
		return fail("expected a subcommand: windows, range, or merge")
	}
	if len(cmd.files) == 0 {
		return fail("--file is required")
	}
	switch sub {
	case "merge":
		if cmd.hasFrom || cmd.hasTo {
			return fail("--from and --to belong to the range subcommand")
		}
		if len(cmd.files) != 2 {
			return fail("merge takes exactly two --file arguments, got %d", len(cmd.files))
		}
	case "range":
		if len(cmd.files) != 1 {
			return fail("range takes exactly one --file argument, got %d", len(cmd.files))
		}
		if !cmd.hasFrom {
			return fail("--from is required")
		}
		if !cmd.hasTo {
			return fail("--to is required")
		}
	default: // windows
		if cmd.hasFrom || cmd.hasTo {
			return fail("--from and --to belong to the range subcommand")
		}
	}
	if cmd.window == "" {
		return fail("--window is required")
	}
	return cmd, true
}

// ingestFile opens one input file and streams its samples into a fresh
// roller. It returns a non-zero exit code after writing one diagnostic if
// the file cannot be opened or its contents are invalid.
func ingestFile(path string, d time.Duration, stderr io.Writer) (*rollup.Roller, int) {
	info, err := os.Stat(path)
	if err != nil {
		fmt.Fprintf(stderr, "rollupctl: %s\n", err)
		return nil, 3
	}
	if info.IsDir() {
		fmt.Fprintf(stderr, "rollupctl: %s: is a directory\n", path)
		return nil, 3
	}
	f, err := os.Open(path)
	if err != nil {
		fmt.Fprintf(stderr, "rollupctl: %s\n", err)
		return nil, 3
	}
	roller, code := ingest(f, path, d, stderr)
	f.Close()
	if code != 0 {
		return nil, code
	}
	return roller, 0
}

// ingest streams the samples from in into a fresh roller. On any content
// problem it returns code 4 after writing one diagnostic naming the file
// and line; no sample lines are printed by the caller in that case.
func ingest(in io.Reader, name string, d time.Duration, stderr io.Writer) (*rollup.Roller, int) {
	contentError := func(line int, reason string) (*rollup.Roller, int) {
		fmt.Fprintf(stderr, "rollupctl: %s:%d: %s\n", name, line, reason)
		return nil, 4
	}

	// The line buffer is capped at one byte over the limit, so a longer
	// line fails immediately instead of growing with the file.
	sc := bufio.NewScanner(in)
	sc.Buffer(make([]byte, maxLineBytes+1), maxLineBytes+1)

	roller := rollup.New(d)
	line := 0
	samples := 0
	for sc.Scan() {
		line++
		text := sc.Text()
		if strings.TrimSpace(text) == "" {
			continue
		}
		fields := strings.Fields(text)
		if len(fields) != 2 {
			return contentError(line, "expected a nanosecond timestamp and a value separated by whitespace")
		}
		ns, err := strconv.ParseInt(fields[0], 10, 64)
		if err != nil {
			return contentError(line, fmt.Sprintf("invalid timestamp %q", fields[0]))
		}
		value, err := strconv.ParseFloat(fields[1], 64)
		if err != nil {
			return contentError(line, fmt.Sprintf("invalid value %q", fields[1]))
		}
		if math.IsNaN(value) || math.IsInf(value, 0) {
			return contentError(line, "value must be finite")
		}
		if err := roller.Add(time.Unix(0, ns).UTC(), value); err != nil {
			return contentError(line, err.Error())
		}
		samples++
	}
	if err := sc.Err(); err != nil {
		if errors.Is(err, bufio.ErrTooLong) {
			// The over-long line is the one after every line already
			// delivered, including an unterminated last line.
			return contentError(line+1, "line is longer than 1024 bytes")
		}
		fmt.Fprintf(stderr, "rollupctl: %s: %v\n", name, err)
		return nil, 3
	}
	if samples == 0 {
		return contentError(0, "no samples found")
	}
	return roller, 0
}

// formatFloat writes a float64 in its shortest round-trippable form; a
// negative zero keeps its sign and renders as -0.
func formatFloat(v float64) string {
	return strconv.FormatFloat(v, 'g', -1, 64)
}

var bigBillion = big.NewInt(1e9)

// unixNanoText writes a window start as a signed integer count of
// nanoseconds since the epoch even when it falls outside the int64 range,
// so a start aligned past it is printed exactly instead of clamped.
func unixNanoText(t time.Time) string {
	n := new(big.Int).Mul(big.NewInt(t.Unix()), bigBillion)
	n.Add(n, big.NewInt(int64(t.Nanosecond())))
	return n.String()
}

package rollup

import (
	"math"
	"math/big"
	"sync"
)

// stats holds the exact bookkeeping behind one Window's Sum, Min, and Max.
// The Window values stay populated on every write and hold the latest
// canonical result; stats keeps what the float64 values alone cannot:
//
//   - sum is the exact real sum of every finite sample filed into the
//     window while its lineage is exact, as one integer at a fixed binary
//     scale: the sum equals sum*2^scale. Every finite float64 is an
//     integer multiple of a power of two, so the representation is exact;
//     there is no denominator and no reduction. Float64 addition rounds
//     after every step and therefore depends on submission order, while
//     the exact integer does not, so it is rounded to float64 once, at
//     write time, and every interleaving of the same sample set rounds to
//     the same bits. The integer is kept even while the current set
//     rounds to an infinity, because later samples can bring the exact
//     sum back into the finite range.
//   - negZero/posZero/nonZero record the kinds of values the window
//     holds, so the sign of a zero sum and of zero extrema is fixed by
//     the sample set rather than by arithmetic residue.
//   - nan/infPlus/infMinus are sticky IEEE states entered only by merging
//     already-rounded window sums (+Inf and -Inf combine to NaN, an
//     infinity stays an infinity once finite values are folded in). A
//     window grown purely through Add never enters them: its overflow is
//     read off the exact integer and remains recoverable.
//
// Windows built directly in the package's tests carry no stats, so a
// virgin stats seeded from such a window absorbs its stored Sum on first
// touch.
type stats struct {
	sum         *big.Int
	scale       int
	initialized bool
	negZero     bool // the window holds at least one -0 sample
	posZero     bool // the window holds at least one +0 sample
	nonZero     bool // the window holds at least one non-zero sample
	infMinus    bool // a merge fixed the sum at -Inf
	infPlus     bool // a merge fixed the sum at +Inf
	nan         bool // a merge combined opposite infinities to NaN
}

// negZeroVal is the negative zero float64.
var negZeroVal = math.Copysign(0, -1)

// intPool recycles the temporary integer each accumulate needs, so filing
// into a steady-state window allocates no scratch operand.
var intPool = sync.Pool{New: func() any { return new(big.Int) }}

// floatPool recycles the big.Float used only while rounding an exact sum.
var floatPool = sync.Pool{New: func() any { return new(big.Float) }}

// seedStats returns bookkeeping for a window freshly created from one
// finite sample.
func seedStats(value float64) stats {
	var st stats
	st.initialized = true
	st.accumulate(value)
	return st
}

// decompose returns the finite float64 value as an odd integer mantissa m
// and exponent e with value = m*2^e, along with the sign. Zero is not
// handled here.
func decompose(value float64) (m uint64, e int, neg bool) {
	bits := math.Float64bits(value)
	neg = bits>>63 == 1
	expb := int((bits >> 52) & 0x7ff)
	mant := bits & (1<<52 - 1)
	switch expb {
	case 0:
		// Subnormal: value = mant*2^-1074. Normalize to an odd m.
		m = mant
		e = -1074
		for m != 0 && m&1 == 0 {
			m >>= 1
			e++
		}
	default:
		m = mant | 1<<52
		e = expb - 1023 - 52
	}
	return m, e, neg
}

// accumulate folds one finite sample into the exact sum. A sticky
// non-finite state from a merge is unchanged: an infinity stays infinite
// and NaN stays NaN when a finite value is added.
func (st *stats) accumulate(value float64) {
	if value == 0 {
		if math.Signbit(value) {
			st.negZero = true
		} else {
			st.posZero = true
		}
		return
	}
	st.nonZero = true
	if st.infMinus || st.infPlus || st.nan {
		return
	}
	mu, e, neg := decompose(value)
	if st.sum == nil {
		st.sum = new(big.Int).SetUint64(mu)
		if neg {
			st.sum.Neg(st.sum)
		}
		st.scale = e
		return
	}
	tmp := intPool.Get().(*big.Int).SetUint64(mu)
	if neg {
		tmp.Neg(tmp)
	}
	if e > st.scale {
		tmp.Lsh(tmp, uint(e-st.scale))
	} else if e < st.scale {
		st.sum.Lsh(st.sum, uint(st.scale-e))
		st.scale = e
	}
	st.sum.Add(st.sum, tmp)
	intPool.Put(tmp)
}

// roundedSum rounds the exact integer sum to float64.
func (st *stats) roundedSum() float64 {
	f := floatPool.Get().(*big.Float)
	f.SetInt(st.sum)
	f.SetMantExp(f, st.scale)
	v, _ := f.Float64()
	floatPool.Put(f)
	return v
}

// absorb seeds bookkeeping from a Window assembled without stats (the
// package's tests build such windows directly). It is called only on a
// virgin stats.
func (st *stats) absorb(w Window) {
	st.initialized = true
	switch {
	case math.IsNaN(w.Sum):
		st.nan = true
	case math.IsInf(w.Sum, 1):
		st.infPlus = true
	case math.IsInf(w.Sum, -1):
		st.infMinus = true
	case w.Sum != 0:
		st.nonZero = true
		mu, e, neg := decompose(w.Sum)
		st.sum = new(big.Int).SetUint64(mu)
		if neg {
			st.sum.Neg(st.sum)
		}
		st.scale = e
	}
	if w.Min == 0 && math.Signbit(w.Min) {
		st.negZero = true
	}
	if w.Max == 0 && !math.Signbit(w.Max) {
		st.posZero = true
	}
}

// kind classifies a sum state for IEEE-style combination by a merge.
type sumKind int

const (
	kindFinite sumKind = iota
	kindPlusInf
	kindMinusInf
	kindNaN
)

// kindOf reports how the sum currently rounds. A window with no non-zero
// samples is a finite zero. Overflow is classified by the exact integer's
// magnitude, so the common finite case never rounds through big.Float.
func (st *stats) kindOf() sumKind {
	switch {
	case st.nan:
		return kindNaN
	case st.infPlus:
		return kindPlusInf
	case st.infMinus:
		return kindMinusInf
	case st.sum == nil:
		return kindFinite
	}
	// |sum| lies in [2^(B-1), 2^B), so its value spans
	// [2^(B-1+scale), 2^(B+scale)). Values at or above 2^1024 round to
	// infinity; below that band they round finite (possibly to zero).
	hi := st.sum.BitLen() - 1 + st.scale
	if hi >= 1024 {
		if st.sum.Sign() < 0 {
			return kindMinusInf
		}
		return kindPlusInf
	}
	return kindFinite
}

// combine folds other's bookkeeping into st, as merging two windows over
// the same start does. When both windows' sums are still finite, the
// union stays exact: merging finite rollers reads the same as filing all
// their samples into one window. Once either side's sum has overflowed to
// a rounded +/-Inf, the two rounded sums combine by the IEEE rules
// (+Inf with -Inf is NaN, an infinity absorbs a finite value), and that
// result sticks. A zero-only window carries the finite zero.
func (st *stats) combine(other *stats) {
	if !other.initialized {
		return
	}
	if !st.initialized {
		*st = *other
		if other.sum != nil {
			st.sum = new(big.Int).Set(other.sum)
		}
		return
	}
	st.negZero = st.negZero || other.negZero
	st.posZero = st.posZero || other.posZero
	st.nonZero = st.nonZero || other.nonZero

	ka, kb := st.kindOf(), other.kindOf()
	switch {
	case ka == kindNaN || kb == kindNaN:
		st.setSticky(kindNaN)
	case ka == kindPlusInf && kb == kindMinusInf, ka == kindMinusInf && kb == kindPlusInf:
		st.setSticky(kindNaN)
	case ka == kindPlusInf || kb == kindPlusInf:
		st.setSticky(kindPlusInf)
	case ka == kindMinusInf || kb == kindMinusInf:
		st.setSticky(kindMinusInf)
	default:
		// Both sides finite: keep the union exact at the finer scale.
		st.infMinus, st.infPlus, st.nan = false, false, false
		switch {
		case st.sum != nil && other.sum != nil:
			target := st.scale
			if other.scale < target {
				target = other.scale
			}
			tmp := intPool.Get().(*big.Int)
			if other.scale == target {
				tmp.Set(other.sum)
			} else {
				tmp.Lsh(other.sum, uint(other.scale-target))
			}
			if st.scale != target {
				st.sum.Lsh(st.sum, uint(st.scale-target))
				st.scale = target
			}
			st.sum.Add(st.sum, tmp)
			intPool.Put(tmp)
		case other.sum != nil:
			st.sum = new(big.Int).Set(other.sum)
			st.scale = other.scale
		}
	}
}

// setSticky forces the named non-finite sticky state and drops the exact
// integer; kindFinite merely clears the sticky flags.
func (st *stats) setSticky(k sumKind) {
	switch k {
	case kindNaN:
		st.nan, st.infPlus, st.infMinus = true, false, false
		st.sum = nil
	case kindPlusInf:
		st.nan, st.infPlus, st.infMinus = false, true, false
		st.sum = nil
	case kindMinusInf:
		st.nan, st.infPlus, st.infMinus = false, false, true
		st.sum = nil
	default:
		st.nan, st.infPlus, st.infMinus = false, false, false
	}
}

// double folds a window's sum with itself, as merging a roller into
// itself does. An exact integer doubles exactly (it may round to
// infinity, which canonicalSum reports); a sticky non-finite sum follows
// the IEEE rules (+Inf doubled is +Inf, NaN doubled is NaN).
func (st *stats) double() {
	if st.sum != nil {
		st.sum.Lsh(st.sum, 1)
		return
	}
	switch st.stickyKind() {
	case kindPlusInf:
		st.setSticky(kindPlusInf)
	case kindMinusInf:
		st.setSticky(kindMinusInf)
	case kindNaN:
		st.setSticky(kindNaN)
	}
}

// stickyKind reports the forced non-finite state of a window with no
// exact integer, or kindFinite when it is merely zero-only.
func (st *stats) stickyKind() sumKind {
	switch {
	case st.nan:
		return kindNaN
	case st.infPlus:
		return kindPlusInf
	case st.infMinus:
		return kindMinusInf
	default:
		return kindFinite
	}
}

// canonicalSum rounds the exact sum to the float64 value the contract
// fixes: NaN from opposite infinities, +/-Inf from one-sided overflow, a
// negative zero only when every sample was a negative zero, and otherwise
// the nearest float64 to the exact sum. A nonzero exact sum that rounds
// to zero still comes out positive zero: only an all-negative-zero
// window may carry the sign.
func (st *stats) canonicalSum() float64 {
	switch {
	case st.nan:
		return math.NaN()
	case st.infPlus:
		return math.Inf(1)
	case st.infMinus:
		return math.Inf(-1)
	case !st.nonZero:
		if st.negZero && !st.posZero {
			return negZeroVal
		}
		return 0
	case st.sum == nil:
		return 0
	}
	v := st.roundedSum()
	if v == 0 {
		return 0
	}
	return v
}

// canonicalMin fixes a minimum that is zero: it is a negative zero when
// the window holds a negative-zero sample, and a positive zero otherwise.
func canonicalMin(v float64, negZero bool) float64 {
	if v == 0 && negZero {
		return negZeroVal
	}
	return v
}

// canonicalMax fixes a maximum that is zero: a positive zero wins
// whenever a positive-zero sample is present; with none, a negative zero
// keeps its sign. A strictly positive maximum keeps its value.
func canonicalMax(v float64, negZero, posZero bool) float64 {
	if v == 0 {
		switch {
		case posZero:
			return 0
		case negZero:
			return negZeroVal
		}
	}
	return v
}

// addTo folds one finite sample into w and its bookkeeping st. Count
// saturates at math.MaxInt64 instead of overflowing; the sum and extrema
// keep updating afterwards under their fixed semantics.
func addTo(w *Window, st *stats, value float64) {
	if w.Count < math.MaxInt64 {
		w.Count++
	}
	st.accumulate(value)
	if value < w.Min {
		w.Min = value
	}
	if value > w.Max {
		w.Max = value
	}
	w.Sum = st.canonicalSum()
	w.Min = canonicalMin(w.Min, st.negZero)
	w.Max = canonicalMax(w.Max, st.negZero, st.posZero)
}

// combineWindow folds src into dst as merging two windows over the same
// start does: counts saturate, the sum states combine, and the extrema
// take the smaller minimum and larger maximum under the zero-sign rules.
func combineWindow(dst *Window, dstSt *stats, src *Window, srcSt *stats) {
	dst.Count = satAdd(dst.Count, src.Count)
	dstSt.combine(srcSt)
	if src.Min < dst.Min {
		dst.Min = src.Min
	}
	if src.Max > dst.Max {
		dst.Max = src.Max
	}
	dst.Sum = dstSt.canonicalSum()
	dst.Min = canonicalMin(dst.Min, dstSt.negZero)
	dst.Max = canonicalMax(dst.Max, dstSt.negZero, dstSt.posZero)
}

// canonicalWindow applies the fixed sum and extrema semantics to w.
func canonicalWindow(w Window, st *stats) Window {
	if !st.initialized {
		return w
	}
	w.Sum = st.canonicalSum()
	w.Min = canonicalMin(w.Min, st.negZero)
	w.Max = canonicalMax(w.Max, st.negZero, st.posZero)
	return w
}

package rollup

import (
	"math"
	"time"
)

// View is a read-only derived view of a Roller at a coarser window size.
// Each view window covers a fixed number of the roller's own windows and
// carries statistics merged from them; no raw samples are re-read. A View
// is a snapshot of the moment it was derived: samples filed, backfilled,
// or merged into the roller afterwards do not alter it.
//
// All methods are safe to call concurrently from multiple goroutines.
type View struct {
	// window is the coarse window size: the roller's window size times
	// the factor the view was derived with. windows is fixed at
	// derivation and read without a lock.
	window  time.Duration
	windows []Window
}

// Rollup derives a read-only view of the roller whose windows are factor
// times wider than the roller's own, aligned to integer multiples of the
// coarser size since the Unix epoch, left-closed and right-open exactly
// like the roller's windows. Each coarse window merges the statistics of
// the roller windows it covers under the same fixed sum and extrema
// semantics as merging: exact sums combine and round once, a minimum
// takes the smaller, and a maximum takes the larger. A factor of 1 yields
// a view window-for-window identical to the roller's own.
//
// Rollup panics with "rollup: bad factor" if factor is not positive, or if
// factor times the roller's window width overflows the range of a
// nanosecond duration: a wrapped coarse width could not align windows to
// the epoch. It is a pure read: the roller's statistics and its most-recent
// marker are untouched, and concurrent adds, batches, backfills, and merges
// proceed as usual — the view observes one consistent snapshot of the
// roller.
func (r *Roller) Rollup(factor int) *View {
	if factor <= 0 {
		panic("rollup: bad factor")
	}
	if int64(factor) > math.MaxInt64/r.window.Nanoseconds() {
		panic("rollup: bad factor")
	}
	coarse := time.Duration(factor) * r.window
	w := coarse.Nanoseconds()

	r.mu.RLock()
	defer r.mu.RUnlock()
	fine, fstats := r.snapshotStatsLocked()
	// The coarse start is monotone in the fine start, so covered windows
	// are consecutive and the whole derivation is one linear pass with a
	// single output allocation bounded by the number of fine windows.
	windows := make([]Window, 0, len(fine))
	cstats := make([]stats, 0, len(fine))
	for i := range fine {
		f := fine[i]
		start := alignStart(f.Start, w)
		if n := len(windows); n != 0 && windows[n-1].Start.Equal(start) {
			combineWindow(&windows[n-1], &cstats[n-1], &f, &fstats[i])
		} else {
			st := cloneStats(fstats[i])
			cw := Window{
				Start: start,
				Count: f.Count,
				Sum:   f.Sum,
				Min:   f.Min,
				Max:   f.Max,
			}
			windows = append(windows, canonicalWindow(cw, &st))
			cstats = append(cstats, st)
		}
	}
	return &View{window: coarse, windows: windows}
}

// Window returns the coarse window whose start matches start exactly, by
// the same exact-match rule as the roller's Window. A start no coarse
// window begins at yields the zero Window and no error; whether the window
// exists is told from its sample count. The returned Window is a copy and
// stays valid no matter what is filed into the roller afterwards.
func (v *View) Window(start time.Time) Window {
	if i, ok := windowIndex(v.windows, start); ok {
		return v.windows[i]
	}
	return Window{}
}

// Range returns the coarse windows overlapping the half-open interval
// [from, to), in time order, selected by the same rule as the roller's
// Range: the first window returned is the one containing from, and a
// window starting exactly at to is excluded. An interval whose end does not
// come after its start yields an empty slice, as does an interval no
// coarse window overlaps.
func (v *View) Range(from, to time.Time) []Window {
	out := []Window{}
	if !from.Before(to) {
		return out
	}
	i, _ := windowIndex(v.windows, alignStart(from, v.window.Nanoseconds()))
	for ; i < len(v.windows); i++ {
		w := v.windows[i]
		if !w.Start.Before(to) {
			break
		}
		out = append(out, w)
	}
	return out
}

// Cursor returns a cursor over the coarse windows overlapping the
// half-open interval [from, to), selected by the same rule as Range. The
// view is already a snapshot, so the cursor's batches never tear, skip,
// or repeat a window no matter what is filed into the roller while the
// cursor advances.
func (v *View) Cursor(from, to time.Time) *Cursor {
	return &Cursor{windows: v.Range(from, to)}
}

