11	// TestConcurrentAddAndRead files samples from many goroutines while others
12	// read windows and snapshots; the final statistics must account for every
13	// accepted sample exactly once. Run with -race to catch data races.
14	func TestConcurrentAddAndRead(t *testing.T) {
15		r := New(2500 * time.Millisecond) // non-integer-second window
16		const writers = 8
17		const perWriter = 200
18	
19		// Readers run for the whole duration; every snapshot they see must be
20		// internally consistent (Min <= Max, Count > 0 in every bucket).
21		stop := make(chan struct{})
22		var readers sync.WaitGroup
23		for i := 0; i < 2; i++ {
24			readers.Add(1)
25			go func() {
26				defer readers.Done()
27				for {
28					select {
29					case <-stop:
30						return
31					default:
32					}
33					for _, w := range r.Windows() {
34						if w.Count <= 0 || w.Min > w.Max {
35							t.Errorf("inconsistent snapshot: %+v", w)
36						}
37					}
38					r.Window(time.Unix(0, 0))
39				}
40			}()
41		}
42	
43		// Each writer files perWriter samples at ever-increasing instants.
44		// Interleaved across writers, some legitimately lose the out-of-order
45		// race; count how many were accepted and expect exactly that many in
46		// the final statistics.
47		var accepted atomic.Int64
48		var writersWg sync.WaitGroup
49		for w := 0; w < writers; w++ {
50			writersWg.Add(1)
51			go func(w int) {
52				defer writersWg.Done()
53				for i := 0; i < perWriter; i++ {
54					at := time.Unix(0, int64(i)*int64(2500*time.Millisecond)+int64(w))
55					err := r.Add(at, float64(w))
56					switch {
57					case err == nil:
58						accepted.Add(1)
59					case errors.Is(err, ErrOutOfOrder):
60						// Lost the race to a later sample; fine.
61					default:
62						t.Errorf("Add: %v", err)
63					}
64				}
65			}(w)
66		}
67		writersWg.Wait()
68		close(stop)
69		readers.Wait()
70	
71		var total int64
72		for _, w := range r.Windows() {
73			total += w.Count
74		}
75		if total != accepted.Load() {
76			t.Fatalf("total count = %d, want %d accepted samples", total, accepted.Load())
77		}
78	}
79	
80	// TestSnapshotIsStable verifies that a slice returned by Windows is not
81	// affected by samples filed afterwards.
82	func TestSnapshotIsStable(t *testing.T) {
83		r := New(time.Minute)
84		if err := r.Add(time.Unix(0, 0), 1); err != nil {
85			t.Fatal(err)
86		}
87		snap := r.Windows()
88		if len(snap) != 1 || snap[0].Count != 1 {
89			t.Fatalf("snapshot before: %v", snap)
90		}
91		if err := r.Add(time.Unix(0, 0), 100); err != nil {
92			t.Fatal(err)
93		}
94		if err := r.Add(time.Unix(60, 0), 5); err != nil {
95			t.Fatal(err)
96		}
97		if len(snap) != 1 || snap[0].Count != 1 || snap[0].Sum != 1 {
98			t.Fatalf("snapshot changed after later writes: %v", snap)
99		}
100	}
101	
102	// TestConcurrentMutualMerge merges two rollers into each other at the same
103	// time; the outcome must match one of the two serial orders.
104	func TestConcurrentMutualMerge(t *testing.T) {
105		for trial := 0; trial < 50; trial++ {
106			a := New(time.Minute)
107			b := New(time.Minute)
108			if err := a.Add(time.Unix(0, 0), 1); err != nil {
109				t.Fatal(err)
110			}
111			if err := b.Add(time.Unix(0, 0), 1); err != nil {
112				t.Fatal(err)
113			}
114			var wg sync.WaitGroup
115			wg.Add(2)
116			go func() { defer wg.Done(); a.Merge(b) }()
117			go func() { defer wg.Done(); b.Merge(a) }()
118			wg.Wait()
119	
120			wa, _ := a.Window(time.Unix(0, 0))
121			wb, _ := b.Window(time.Unix(0, 0))
122			// Serial orders: a-then-b gives (2, 3); b-then-a gives (3, 2).
123			ab := wa.Count == 2 && wb.Count == 3
124			ba := wa.Count == 3 && wb.Count == 2
125			if !ab && !ba {
126				t.Fatalf("trial %d: counts (%d, %d) match no serial order", trial, wa.Count, wb.Count)
127			}
128			if wa.Sum != float64(wa.Count) || wb.Sum != float64(wb.Count) {
129				t.Fatalf("trial %d: sums (%v, %v) inconsistent with counts", trial, wa.Sum, wb.Sum)
130			}
131		}
132	}
