23			t.Fatal(err)
24		}
25		w, ok := r.Window(time.Unix(0, 0))
26		if !ok {
27			t.Fatal("window at 0 missing")
28		}
29		if w.Count != 3 || w.Sum != 3 || w.Min != 1 || w.Max != 1 {
30			t.Fatalf("window 0: %+v", w)
